//! Native tCn vectors are generated by tool_result_pairing_319_oracle.mjs
//! from the pinned executable, including its exact createUserMessage helper.
use super::*;
use serde_json::{json, Value};

fn fixture() -> Value {
    serde_json::from_str(include_str!(
        "../tests/fixtures/tool_result_pairing_2_1_319.json"
    ))
    .unwrap()
}

fn fixture_block(block: &Value, force_raw: bool) -> ProtoBlock {
    if force_raw {
        return ProtoBlock::ProviderContent {
            protocol: "anthropic_messages".into(),
            value: Utf16JsonProjection::parse(&block.to_string()).unwrap(),
        };
    }
    serde_json::from_value(block.clone()).unwrap_or_else(|_| ProtoBlock::ProviderContent {
        protocol: "anthropic_messages".into(),
        value: Utf16JsonProjection::parse(&block.to_string()).unwrap(),
    })
}

fn fixture_rows(test_case: &Value) -> Vec<ConversationMessage> {
    test_case["input"]
        .as_array()
        .unwrap()
        .iter()
        .enumerate()
        .map(|(row_index, row)| {
            let native_content = &row["message"]["content"];
            let content = if let Some(text) = native_content.as_str() {
                vec![ProtoBlock::Text {
                    text: text.into(),
                    citations: None,
                }]
            } else {
                native_content
                    .as_array()
                    .unwrap()
                    .iter()
                    .enumerate()
                    .map(|(block_index, block)| {
                        let raw = test_case["raw_blocks"].as_array().is_some_and(|indices| {
                            indices
                                .iter()
                                .any(|index| index == &json!([row_index, block_index]))
                        });
                        fixture_block(block, raw)
                    })
                    .collect()
            };
            let id = MessageId::new();
            if row["type"] == "assistant" {
                ConversationMessage::Assistant {
                    id,
                    content,
                    stop_reason: None,
                    resumable: None,
                    per_turn_effort: None,
                }
            } else {
                let mut message = ConversationMessage::user(id, String::new());
                let ConversationMessage::User {
                    content: user_content,
                    is_meta,
                    interrupted_by_shutdown,
                    refused_message_id,
                    ..
                } = &mut message
                else {
                    unreachable!()
                };
                *user_content = content;
                *is_meta = row["isMeta"].as_bool().unwrap_or(false);
                *interrupted_by_shutdown = row["interruptedByShutdown"].as_bool();
                *refused_message_id = row
                    .get("refusedMessageId")
                    .map(|value| Utf16JsonProjection::parse(&value.to_string()).unwrap());
                message
            }
        })
        .collect()
}

fn project_block(block: &ProtoBlock) -> Value {
    match block {
        ProtoBlock::ProviderContent { value, .. } => {
            serde_json::from_str(&value.to_json_string().unwrap()).unwrap()
        }
        _ => serde_json::to_value(block).unwrap(),
    }
}

fn project_rows(messages: &[ConversationMessage]) -> Value {
    Value::Array(
        messages
            .iter()
            .map(|message| match message {
                ConversationMessage::Assistant { content, .. } => json!({
                    "role": "assistant",
                    "content": content.iter().map(project_block).collect::<Vec<_>>(),
                }),
                ConversationMessage::User {
                    content,
                    is_meta,
                    interrupted_by_shutdown,
                    refused_message_id,
                    ..
                } => {
                    let mut row = json!({
                        "role": "user",
                        "content": content.iter().map(project_block).collect::<Vec<_>>(),
                        "is_meta": is_meta,
                    });
                    if let Some(value) = interrupted_by_shutdown {
                        row["interrupted_by_shutdown"] = json!(value);
                    }
                    if let Some(value) = refused_message_id {
                        row["refused_message_id"] =
                            serde_json::from_str(&value.to_json_string().unwrap()).unwrap();
                    }
                    row
                }
                _ => panic!("pairing fixtures contain only model conversation rows"),
            })
            .collect(),
    )
}

#[test]
fn pairing_matches_native_319_source_vectors() {
    let fixture = fixture();
    assert_eq!(fixture["version"], "2.1.319");
    assert_eq!(
        fixture["binary_sha256"],
        "1f53587e92dee8e089fa349188a4cda64fa34ace6e7b0ca2ee278ddaa3cc2ebd"
    );
    assert_eq!(fixture["cases"].as_array().unwrap().len(), 28);
    for test_case in fixture["cases"].as_array().unwrap() {
        let actual = ensure_tool_result_pairing(fixture_rows(test_case));
        assert_eq!(
            project_rows(&actual),
            test_case["expected"],
            "{}",
            test_case["name"]
        );
    }
}

#[test]
fn missing_result_order_is_stable_across_hash_seeds_and_keeps_sources() {
    let fixture = fixture();
    let test_case = fixture["cases"]
        .as_array()
        .unwrap()
        .iter()
        .find(|case| case["name"] == "missing_results_follow_tool_use_order")
        .unwrap();
    for _ in 0..64 {
        let input = ConversationMessagesWithSources::new(fixture_rows(test_case));
        let source = input.messages[0].id();
        let actual = ensure_tool_result_pairing_with_sources(input);
        assert_eq!(project_rows(&actual.messages), test_case["expected"]);
        assert_eq!(actual.block_sources.len(), 2);
        assert_eq!(actual.block_sources[1].len(), 4);
        assert!(actual.block_sources[1]
            .iter()
            .all(|sources| sources == &HashSet::from([source])));
    }
}

#[test]
fn removed_tool_spacer_keeps_its_source_identity() {
    let fixture = fixture();
    let test_case = fixture["cases"]
        .as_array()
        .unwrap()
        .iter()
        .find(|case| case["name"] == "misplaced_result_between_thinking_gets_spacer")
        .unwrap();
    let mut input = ConversationMessagesWithSources::new(fixture_rows(test_case));
    let removed_source = MessageId::new();
    input.block_sources[0][1] = HashSet::from([removed_source]);
    let actual = ensure_tool_result_pairing_with_sources(input);
    assert_eq!(project_rows(&actual.messages), test_case["expected"]);
    assert_eq!(actual.block_sources[0][1], HashSet::from([removed_source]));
}

#[test]
fn repaired_user_body_is_not_replaced_by_a_stale_api_override() {
    let fixture = fixture();
    for name in [
        "leading_orphan_preserves_text",
        "duplicate_and_orphan_results_are_removed",
    ] {
        let test_case = fixture["cases"]
            .as_array()
            .unwrap()
            .iter()
            .find(|case| case["name"] == name)
            .unwrap();
        let mut input = fixture_rows(test_case);
        let ConversationMessage::User {
            content,
            api_message_override,
            ..
        } = input.last_mut().unwrap()
        else {
            panic!("fixture ends in the user row being repaired");
        };
        *api_message_override = Some(lingxi_core::types::ApiSystemMessage {
            content: content.clone(),
            output_config: None,
        });
        let repaired = ensure_tool_result_pairing(input);
        let outgoing = normalize_messages_for_api(repaired);
        assert_eq!(project_rows(&outgoing), test_case["expected"]);
        let converted = to_llm_messages(outgoing).unwrap();
        assert!(converted.iter().all(|message| message.role != "system"));
    }
}

fn source_fixture_rows(source: &str) -> Vec<ConversationMessage> {
    let rows = Utf16JsonProjection::parse(source).unwrap();
    (0..rows.array_len("").unwrap())
        .map(|index| {
            let row = rows.subprojection(&format!("/{index}")).unwrap();
            let content = (0..row.array_len("/message/content").unwrap())
                .map(|block| ProtoBlock::ProviderContent {
                    protocol: "anthropic_messages".into(),
                    value: row
                        .subprojection(&format!("/message/content/{block}"))
                        .unwrap(),
                })
                .collect();
            let id = MessageId::new();
            if row.string_at("/type") == Some("assistant") {
                ConversationMessage::Assistant {
                    id,
                    content,
                    stop_reason: None,
                    resumable: None,
                    per_turn_effort: None,
                }
            } else {
                let mut message = ConversationMessage::user(id, String::new());
                let ConversationMessage::User {
                    content: user_content,
                    is_meta,
                    interrupted_by_shutdown,
                    refused_message_id,
                    ..
                } = &mut message
                else {
                    unreachable!();
                };
                *user_content = content;
                *is_meta = row
                    .at_pointer("/isMeta")
                    .and_then(JsonValueView::as_bool)
                    .unwrap_or(false);
                *interrupted_by_shutdown = row
                    .at_pointer("/interruptedByShutdown")
                    .and_then(JsonValueView::as_bool);
                *refused_message_id = row.subprojection("/refusedMessageId").ok();
                message
            }
        })
        .collect()
}

fn project_source_rows(messages: &[ConversationMessage]) -> Utf16JsonProjection {
    Utf16JsonProjection::array(
        messages
            .iter()
            .map(|message| {
                let (role, content) = match message {
                    ConversationMessage::Assistant { content, .. } => ("assistant", content),
                    ConversationMessage::User { content, .. } => ("user", content),
                    _ => panic!("pairing vectors contain only model rows"),
                };
                let content = Utf16JsonProjection::array(
                    content
                        .iter()
                        .map(|block| match block {
                            ProtoBlock::ProviderContent { value, .. } => value.clone(),
                            // Typed generated blocks contain no unpaired IDs;
                            // this serializer still retains projection fields.
                            _ => Utf16JsonProjection::parse(&serde_json::to_string(block).unwrap())
                                .unwrap(),
                        })
                        .collect(),
                )
                .unwrap();
                let mut fields = vec![("role".into(), role.into()), ("content".into(), content)];
                if let ConversationMessage::User {
                    is_meta,
                    interrupted_by_shutdown,
                    refused_message_id,
                    ..
                } = message
                {
                    let boolean = |value| {
                        Utf16JsonProjection::parse(if value { "true" } else { "false" }).unwrap()
                    };
                    fields.push(("is_meta".into(), boolean(*is_meta)));
                    if let Some(value) = interrupted_by_shutdown {
                        fields.push(("interrupted_by_shutdown".into(), boolean(*value)));
                    }
                    if let Some(value) = refused_message_id {
                        fields.push(("refused_message_id".into(), value.clone()));
                    }
                }
                Utf16JsonProjection::object(fields).unwrap()
            })
            .collect(),
    )
    .unwrap()
}

#[test]
fn source_pairing_ids_keep_exact_units_and_provider_fields() {
    let fixture = fixture();
    assert_eq!(fixture["source_cases"].as_array().unwrap().len(), 8);
    for case in fixture["source_cases"].as_array().unwrap() {
        // Outer fixture values hold JSON *documents* as strings. Source IDs,
        // bodies, metadata and provider fields never pass through Value.
        let input = source_fixture_rows(case["input_json"].as_str().unwrap());
        let durable_source = project_source_rows(&input).to_json_string().unwrap();
        let actual = ensure_tool_result_pairing(input.clone());
        assert_eq!(
            project_source_rows(&actual)
                .to_json_string()
                .unwrap()
                .as_bytes(),
            case["expected_rows_json"].as_str().unwrap().as_bytes(),
            "{}",
            case["name"]
        );
        assert_eq!(
            project_source_rows(&input).to_json_string().unwrap(),
            durable_source,
            "the repair must preserve its durable source: {}",
            case["name"]
        );
    }
}

#[test]
fn distinct_lone_ids_keep_distinct_synthetic_result_sources() {
    let fixture = fixture();
    let case = fixture["source_cases"]
        .as_array()
        .unwrap()
        .iter()
        .find(|case| case["name"] == "distinct_lone_client_ids")
        .unwrap();
    let mut input = ConversationMessagesWithSources::new(source_fixture_rows(
        case["input_json"].as_str().unwrap(),
    ));
    let first = MessageId::new();
    let second = MessageId::new();
    input.block_sources[0] = vec![HashSet::from([first]), HashSet::from([second])];
    let actual = ensure_tool_result_pairing_with_sources(input);
    assert_eq!(
        actual.block_sources[1],
        vec![HashSet::from([first]), HashSet::from([second])]
    );
    let ConversationMessage::User { content, .. } = &actual.messages[1] else {
        panic!("expected synthesized results");
    };
    assert_eq!(pairing_tool_result_id(&content[0]), Some(vec![0xd800]));
    assert_eq!(pairing_tool_result_id(&content[1]), Some(vec![0xdfff]));
}

#[test]
fn source_pairing_ids_reach_production_conversion_and_sdk_wire() {
    use crate::services::sdk::{self, WireCodec};
    let fixture = fixture();
    let profile: sdk::protocol::ProviderProfile = serde_json::from_value(json!({
        "provider_id":"anthropic", "profile_name":"source-pairing",
        "base_url":"https://api.anthropic.com", "protocol":"anthropic_messages",
        "auth":"none", "models":[]
    }))
    .unwrap();
    for case in fixture["source_cases"].as_array().unwrap() {
        let input = source_fixture_rows(case["input_json"].as_str().unwrap());
        let repaired = ensure_tool_result_pairing(input);
        let runtime_messages = to_llm_messages(normalize_messages_for_api(repaired)).unwrap();
        let (canonical, _) = history_input(
            "claude-sonnet-4-6",
            &runtime_messages,
            &[],
            &[],
            sdk::protocol::ProtocolFamily::AnthropicMessages,
        )
        .unwrap();
        if case["wire"] != true {
            // Hosted admission and typed valid-ID block ordering have their
            // own contracts. The exact source repair is checked above.
            continue;
        }
        let encoded = sdk::AnthropicMessagesCodec
            .encode_request(
                sdk::EncodeRequest::new(&canonical),
                &sdk::CodecContext::new(&profile, &canonical.model, sdk::RequestMode::Complete),
            )
            .unwrap();
        // Compare the codec's original messages slice, without JSON
        // reserialization. Final HTTP surrogate sanitation is a later policy.
        let body = JsonPayload::parse(std::str::from_utf8(&encoded.body).unwrap()).unwrap();
        let wire_messages = body.raw_source_at("/messages").unwrap();
        assert_eq!(
            wire_messages.as_bytes(),
            case["expected_sdk_messages_json"]
                .as_str()
                .unwrap()
                .as_bytes(),
            "{}",
            case["name"]
        );
        assert!(wire_messages.contains("\\ud800"));
    }
}
